import{_ as t,a as o,o as d,a4 as a}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Themes","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/themes/index.md","filePath":"api/graphql-api/admin/settings/themes/index.md","lastUpdated":1784902076000}'),s={name:"api/graphql-api/admin/settings/themes/index.md"};function r(i,e,n,c,l,h){return d(),o("div",null,e[0]||(e[0]=[a('<h1 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h1><p>The Themes menu controls the <strong>theme customizations</strong> that drive your storefront&#39;s content blocks per sales channel. It mirrors the admin <strong>Settings → Themes</strong> screen.</p><p>Despite the name, this menu does <strong>not</strong> install or switch site templates. Each row is a single content block — a product carousel, a static HTML/CSS snippet, an image slider, a footer-links group, or a service block — bound to one channel and one theme code, with its visible content stored per locale.</p><h2 id="what-each-type-renders" tabindex="-1">What each <code>type</code> renders <a class="header-anchor" href="#what-each-type-renders" aria-label="Permalink to &quot;What each `type` renders&quot;">​</a></h2><p>The <code>type</code> you pick at creation decides what the block renders on the storefront and what shape its per-locale <code>options</code> take.</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>Renders</th></tr></thead><tbody><tr><td><code>product_carousel</code></td><td>A horizontal slider of products selected by filter/sort criteria.</td></tr><tr><td><code>category_carousel</code></td><td>A horizontal slider of categories.</td></tr><tr><td><code>static_content</code></td><td>A free-form HTML + CSS snippet injected into the page.</td></tr><tr><td><code>image_carousel</code></td><td>A rotating banner of slide images, each with a link.</td></tr><tr><td><code>footer_links</code></td><td>A grouped set of footer link columns.</td></tr><tr><td><code>services_content</code></td><td>A row of service blocks (icon + title + description), e.g. &quot;Free Shipping&quot;.</td></tr></tbody></table><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>Internal label for the block, shown in the admin grid.</td></tr><tr><td><code>type</code></td><td>The block kind — fixed at creation (see the table above).</td></tr><tr><td><code>sortOrder</code></td><td>Position of this block relative to other blocks on the same channel (lower shows first).</td></tr><tr><td><code>themeCode</code></td><td>The theme code this block belongs to (e.g. <code>default</code>).</td></tr><tr><td><code>channelId</code></td><td>The sales channel this block is bound to.</td></tr><tr><td><code>status</code></td><td><code>true</code> = active (rendered on the storefront), <code>false</code> = inactive.</td></tr><tr><td><code>translations</code></td><td>The per-locale <code>options</code> content, a field-selectable connection (detail only — see below).</td></tr></tbody></table><h2 id="per-locale-options" tabindex="-1">Per-locale <code>options</code> <a class="header-anchor" href="#per-locale-options" aria-label="Permalink to &quot;Per-locale `options`&quot;">​</a></h2><p>A block&#39;s actual content lives in its per-locale <code>options</code> and is <strong>not</strong> set at creation. Create the block with its scalar fields first (step 1), then fill in the content with the <a href="./update.html">Update</a> mutation, passing the target <code>locale</code> and an <code>options</code> object whose shape depends on the block&#39;s <code>type</code>. Repeat per locale to localize the block. The <a href="./detail.html">Detail</a> query returns every locale&#39;s <code>options</code> as a connection — select <code>translations { edges { node { _id locale options } } }</code>.</p><h2 id="what-each-operation-does" tabindex="-1">What each operation does <a class="header-anchor" href="#what-each-operation-does" aria-label="Permalink to &quot;What each operation does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Create</strong></td><td>Creates the block with its step-1 scalars (<code>name</code>, <code>type</code>, <code>sortOrder</code>, <code>themeCode</code>, <code>channelId</code>, <code>status</code>). The block starts with empty <code>translations</code>.</td></tr><tr><td><strong>Update</strong></td><td>Sets the per-locale <code>options</code> for one <code>locale</code>, and/or edits the scalar fields.</td></tr><tr><td><strong>Delete</strong></td><td>Removes the block and wipes its associated storage directory.</td></tr><tr><td><strong>Mass Delete</strong></td><td>Removes several blocks at once by their ids. Non-existent ids are skipped.</td></tr><tr><td><strong>Mass Update Status</strong></td><td>Bulk-sets <code>status</code> (active/inactive) on the selected blocks.</td></tr></tbody></table><h2 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h2><ul><li><strong>Image / file fields are path strings only.</strong> For <code>image_carousel</code> slides and <code>services_content</code> icons, the <code>options</code> accept already-uploaded storage <strong>paths</strong> — binary file upload is not available here. Use the admin panel to upload new files.</li><li><strong><code>&lt;script&gt;</code> is stripped from <code>static_content</code>.</strong> Any <code>&lt;script&gt;...&lt;/script&gt;</code> blocks in a <code>static_content</code> block&#39;s <code>options.html</code> or <code>options.css</code> are removed before saving.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List theme customizations</a></td><td><code>adminSettingsThemes</code> query</td></tr><tr><td><a href="./detail.html">Get a theme customization</a></td><td><code>adminSettingsTheme(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a theme customization</a></td><td><code>createAdminSettingsTheme</code> mutation</td></tr><tr><td><a href="./update.html">Update a theme customization</a></td><td><code>updateAdminSettingsTheme</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a theme customization</a></td><td><code>deleteAdminSettingsTheme</code> mutation</td></tr><tr><td><a href="./mass-delete.html">Mass delete theme customizations</a></td><td><code>createAdminSettingsThemeMassDelete</code> mutation</td></tr><tr><td><a href="./mass-update-status.html">Mass update status</a></td><td><code>createAdminSettingsThemeMassUpdateStatus</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.themes.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',18)]))}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
